/* LifeCare minimal OOXML writer. No remote scripts; cell data is never interpreted as a formula. */
(()=>{
 const encoder=new TextEncoder(), enc=s=>encoder.encode(s), esc=s=>String(s??'').replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\ufffe\uffff]/g,'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[x]));
 const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
 const crc32=b=>{let c=0xffffffff;for(const x of b)c=crcTable[(c^x)&255]^(c>>>8);return (c^0xffffffff)>>>0};
 function zip(files){const parts=[],central=[];let offset=0,centralLen=0;for(const [path,xml] of Object.entries(files)){const name=enc(path),data=typeof xml==='string'?enc(xml):xml,crc=crc32(data),h=new Uint8Array(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,33,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);parts.push(h,name,data);const c=new Uint8Array(46),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(c,name);centralLen+=c.length+name.length;offset+=h.length+name.length+data.length}const end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,Object.keys(files).length,true);e.setUint16(10,Object.keys(files).length,true);e.setUint32(12,centralLen,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
 const col=n=>{let a='';while(n>0){n--;a=String.fromCharCode(65+n%26)+a;n=Math.floor(n/26)}return a};
 const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main', rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships', pn='http://schemas.openxmlformats.org/package/2006/relationships';
 const declaration='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
 function worksheet(rows){const max=Math.max(1,...rows.map(r=>r.length)), last=col(max)+Math.max(1,rows.length);const widths=Array.from({length:max},(_,i)=>Math.min(48,Math.max(12,...rows.slice(0,100).map(r=>String(r[i]??'').length+2))));return declaration+`<worksheet xmlns="${ns}"><dimension ref="A1:${last}"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="16"/><cols>${widths.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')}</cols><sheetData>`+rows.map((row,i)=>`<row r="${i+1}">`+row.map((value,j)=>{const id=col(j+1)+(i+1),style=i===0?' s="1"':'';if(value===null||value===undefined)value='';if(typeof value==='number'&&Number.isFinite(value))return `<c r="${id}"${style}><v>${value}</v></c>`;if(typeof value==='boolean')return `<c r="${id}" t="b"${style}><v>${+value}</v></c>`;const text=Array.from(String(value)).slice(0,32767).join('');return `<c r="${id}" t="inlineStr"${style}><is><t xml:space="preserve">${esc(text)}</t></is></c>`}).join('')+'</row>').join('')+`</sheetData>${rows.length>1?`<autoFilter ref="A1:${last}"/>`:''}</worksheet>`}
 const styles=declaration+`<styleSheet xmlns="${ns}"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF294483"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
 function build(sheets){const used=new Set(),names=sheets.map(({name})=>{const base=String(name||'Responses').replace(/[\\\/:*?\[\]]/g,' ').replace(/^'+|'+$/g,'').trim().slice(0,31)||'Responses';let n=base,i=2;while(used.has(n.toLowerCase())){const suffix=' '+i++;n=base.slice(0,31-suffix.length)+suffix}used.add(n.toLowerCase());return n});const files={};files['[Content_Types].xml']=declaration+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>';files['_rels/.rels']=declaration+`<Relationships xmlns="${pn}"><Relationship Id="rId1" Type="${rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>`;files['xl/workbook.xml']=declaration+`<workbook xmlns="${ns}" xmlns:r="${rel}"><bookViews><workbookView/></bookViews><sheets>`+names.map((n,i)=>`<sheet name="${esc(n)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>';files['xl/_rels/workbook.xml.rels']=declaration+`<Relationships xmlns="${pn}">`+sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${rel}/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+`<Relationship Id="rId${sheets.length+1}" Type="${rel}/styles" Target="styles.xml"/></Relationships>`;files['xl/styles.xml']=styles;sheets.forEach((s,i)=>files[`xl/worksheets/sheet${i+1}.xml`]=worksheet(s.rows));return zip(files)}
 globalThis.LifeCareExcel={build,download(sheets,name){const blob=build(sheets),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/\.xlsx$/i,'')+'.xlsx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}};
})();
